hostedSite.customCss:
.hs-counter { max-width: 36rem; margin: 0 auto; padding: 2.5rem 1.25rem 4rem; text-align: center; }
.hs-sql-widget { margin: 0 0 1.25rem; }
.hs-sql-value { font-size: 4.5rem; font-weight: 750; letter-spacing: -0.07em; line-height: 1; }
.hs-sql-caption { margin-top: 0.65rem; font-size: 0.85rem; color: color-mix(in srgb, var(--hs-fg) 58%, transparent); }
.hs-action-row { display: flex; flex-wrap: wrap; justify-content: center; gap: 0.85rem; align-items: flex-start; }
.hs-action-slot { margin: 0; max-width: 20rem; text-align: center; }
.hs-action-btn { min-width: 10rem; height: 2.6rem; border: 0; border-radius: 999px; background: var(--hs-accent); color: #fff; font-weight: 600; font-size: 0.95rem; cursor: pointer; }
.hs-action-btn:disabled { opacity: 0.6; cursor: wait; }
.hs-step-trace { margin-top: 1rem; padding: 0.85rem 0.9rem; border-radius: 0.9rem; border: 1px solid color-mix(in srgb, var(--hs-fg) 10%, transparent); background: color-mix(in srgb, var(--hs-bg) 92%, #fff); text-align: left; }
